/**  Sorted numerically. */
"number" | 
/**  Derived from the creation time by the UI, so it stays fresh. */
"age" | 
/**  Coloured by value (Running, Pending, Failed, ...). */
"status" | 
/**  Live usage merged in by the UI from the metrics API. */
"podCpu" | "podMemory" | "nodeCpu" | "nodeMemory";

